124→function ErrorBlock({ errorMessage, onRetry }: { errorMessage: string; onRetry?: () => void }) {
125→  const { t } = useTranslation();
126→  return (
127→    <div className="message-bubble__segment message-bubble__segment--error">
128→      <div className="message-bubble__error-header">{t('errorOccurred')}</div>
129→      <div className="message-bubble__error-message">{errorMessage}</div>
130→      {onRetry && (
131→        <button className="message-bubble__error-retry" onClick={onRetry}>
132→          {t('tryAgain')}
133→        </button>
134→      )}
135→    </div>
136→  );
137→}
