139→export function MessageBubble({ message, messageIndex }: { message: ChatMessage; messageIndex: number }) {
140→  const { t } = useTranslation();
141→  const { isStreaming, editMessage, deleteMessage, sendMessage, messages } = useAgent();
142→  const [isEditing, setIsEditing] = useState(false);
143→  const [editText, setEditText] = useState(message.content);
144→  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
145→  const textareaRef = useRef<HTMLTextAreaElement>(null);
146→
147→  const isUser = message.role === 'user';
148→  const hasSegments = !isUser && message.segments && message.segments.length > 0;
149→
150→  useEffect(() => {
151→    if (isEditing && textareaRef.current) {
152→      textareaRef.current.focus();
153→      textareaRef.current.selectionStart = textareaRef.current.value.length;
154→    }
155→  }, [isEditing]);
156→
157→  const handleEdit = () => {
158→    setEditText(message.content);
159→    setIsEditing(true);
160→    setIsConfirmingDelete(false);
161→  };
162→
163→  const handleCancelEdit = () => {
164→    setIsEditing(false);
165→    setEditText(message.content);
166→  };
167→
168→  const handleSaveEdit = () => {
169→    const trimmed = editText.trim();
170→    if (!trimmed || trimmed === message.content) {
171→      handleCancelEdit();
172→      return;
173→    }
174→    setIsEditing(false);
175→    editMessage(messageIndex, trimmed);
176→  };
177→
178→  const handleDeleteConfirm = () => {
179→    setIsConfirmingDelete(false);
180→    deleteMessage(messageIndex);
181→  };
182→
183→  const handleKeyDown = (e: React.KeyboardEvent) => {
184→    if (e.key === 'Escape') {
185→      handleCancelEdit();
186→    } else if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
187→      e.preventDefault();
188→      handleSaveEdit();
189→    }
190→  };
191→
192→  let streamingRemainder: string | undefined;
193→  if (hasSegments && message.isStreaming && message.content) {
194→    const segmentedText = message.segments!
195→      .filter((s) => s.type === 'thinking' || s.type === 'answer')
196→      .map((s) => s.text || '')
197→      .join('');
198→    const remaining = message.content.slice(segmentedText.length);
199→    if (remaining.trim()) {
200→      streamingRemainder = remaining;
201→    }
202→  }
203→
204→  const hasAnswer = !!hasSegments && message.segments!.some((s) => s.type === 'answer');
205→  const isInAnswerPhase = message.currentPhase === 'answer';
206→  const isThinkingPhase = !!message.isStreaming && !hasAnswer && !isInAnswerPhase;
207→
208→  const hasCharts = hasSegments && message.segments!.some(
209→    (s) => (s.type === 'tool' && s.toolResult?.chart_spec) || (s.type === 'subagent_end' && s.chart_spec)
210→  );
211→
212→  const answerBlockSegments = hasSegments
213→    ? message.segments!
214→        .filter((s) =>
215→          (s.type === 'answer' && s.text?.trim()) ||
216→          (s.type === 'subagent_end' && !s.chart_spec && s.text?.trim() && !hasAnswer) ||
217→          (s.type === 'tool' && s.toolResult?.chart_spec) ||
218→          (s.type === 'subagent_end' && s.chart_spec)
219→        )
220→        .map((s) => {
221→          if ((s.type === 'answer' || (s.type === 'subagent_end' && !s.chart_spec)) && s.text && hasCharts) {
222→            return { ...s, text: stripChartSpecBlocks(s.text) };
223→          }
224→          return s;
225→        })
226→        .filter((s) => {
227→          // Remove text segments that became empty after stripping chart blocks
228→          if ((s.type === 'answer' || (s.type === 'subagent_end' && !s.chart_spec)) && !s.text?.trim()) {
229→            return false;
230→          }
231→          return true;
232→        })
233→    : [];
234→
235→  const questionSegments = hasSegments
236→    ? message.segments!.filter((s) => s.type === 'user_question' && s.questionData)
237→    : [];
238→
239→  return (
240→    <div className={`message-bubble message-bubble--${message.role}`}>
241→      <div className="message-bubble__header">
242→        {isUser ? t('you') : t('assistant')}
243→        {isUser && !isStreaming && !isEditing && !isConfirmingDelete && (
244→          <span className="message-bubble__actions">
245→            <button
246→              className="message-bubble__action-btn"
247→              onClick={handleEdit}
248→              title={t('editMessage')}
249→            >
250→              &#9998;
251→            </button>
252→            <button
253→              className="message-bubble__action-btn message-bubble__action-btn--delete"
254→              onClick={() => setIsConfirmingDelete(true)}
255→              title={t('deleteMessage')}
256→            >
257→              &#128465;
258→            </button>
259→          </span>
260→        )}
261→      </div>
262→
263→      {isUser && isConfirmingDelete && (
264→        <div className="message-bubble__confirm-delete">
265→          <span>{t('deleteConfirm')}</span>
266→          <div className="message-bubble__confirm-actions">
267→            <button
268→              className="message-bubble__confirm-btn message-bubble__confirm-btn--delete"
269→              onClick={handleDeleteConfirm}
270→            >
271→              {t('delete')}
272→            </button>
273→            <button
274→              className="message-bubble__confirm-btn"
275→              onClick={() => setIsConfirmingDelete(false)}
276→            >
277→              {t('cancel')}
278→            </button>
279→          </div>
280→        </div>
281→      )}
282→
283→      {isUser && isEditing ? (
284→        <div className="message-bubble__edit-mode">
285→          <textarea
286→            ref={textareaRef}
287→            className="message-bubble__edit-textarea"
288→            value={editText}
289→            onChange={(e) => setEditText(e.target.value)}
290→            onKeyDown={handleKeyDown}
291→            rows={3}
292→          />
293→          <div className="message-bubble__edit-actions">
294→            <button
295→              className="message-bubble__edit-btn message-bubble__edit-btn--save"
296→              onClick={handleSaveEdit}
297→            >
298→              {t('saveResend')}
299→            </button>
300→            <button
301→              className="message-bubble__edit-btn"
302→              onClick={handleCancelEdit}
303→            >
304→              {t('cancel')}
305→            </button>
306→          </div>
307→        </div>
308→      ) : hasSegments ? (
309→        <div className="message-bubble__segments">
310→          {!questionSegments.some((s) => !s.userAnswer) && (
311→            <ThinkingBlock
312→              segments={message.segments!}
313→              streamingRemainder={isThinkingPhase ? streamingRemainder : undefined}
314→              isThinkingPhase={isThinkingPhase}
315→              isAgentStreaming={!!message.isStreaming}
316→              hasAnswer={hasAnswer}
317→            />
318→          )}
319→          {questionSegments.map((seg, i) => (
320→            <div key={`question-${i}`} className="message-bubble__segment message-bubble__segment--question">
321→              <UserQuestion
322→                questionData={seg.questionData!}
323→                userAnswer={seg.userAnswer}
324→                userFreeText={seg.userFreeText}
325→              />
326→            </div>
327→          ))}
328→          {answerBlockSegments.length > 0 && (
329→            <div className="message-bubble__segment message-bubble__segment--answer">
330→              <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
331→              {answerBlockSegments.map((seg, i) => {
332→                // Chart segment (tool with chart_spec or subagent_end with chart_spec)
333→                if ((seg.type === 'tool' && seg.toolResult?.chart_spec) || (seg.type === 'subagent_end' && seg.chart_spec)) {
334→                  return (
335→                    <div key={`chart-${i}`} className="message-bubble__chart-in-answer">
336→                      {seg.type === 'tool' && seg.toolResult ? (
337→                        <InlineQueryResult result={seg.toolResult!} />
338→                      ) : seg.chart_spec ? (
339→                        <ChartWidget data={seg.chart_spec.data} layout={seg.chart_spec.layout} frames={seg.chart_spec.frames} />
340→                      ) : null}
341→                    </div>
342→                  );
343→                }
344→                // Text segment (answer or subagent_end without chart_spec)
345→                return (
346→                  <div key={`answer-${i}`} className="message-bubble__segment-content">
347→                    <ReactMarkdown remarkPlugins={[remarkGfm]}>{seg.text!}</ReactMarkdown>
348→                  </div>
349→                );
350→              })}
351→              {/* Render streaming remainder inside the same answer block to avoid duplicate headers */}
352→              {isInAnswerPhase && streamingRemainder?.trim() && (() => {
353→                const displayText = hasCharts ? stripChartSpecBlocks(streamingRemainder) : streamingRemainder;
354→                return displayText?.trim() ? (
355→                  <div className="message-bubble__segment-content">
356→                    <ReactMarkdown remarkPlugins={[remarkGfm]}>{displayText}</ReactMarkdown>
357→                  </div>
358→                ) : null;
359→              })()}
360→            </div>
361→          )}
362→          {/* Only show standalone streaming answer block when no answer segments exist yet */}
363→          {answerBlockSegments.length === 0 && isInAnswerPhase && streamingRemainder?.trim() && (() => {
364→            const displayText = hasCharts ? stripChartSpecBlocks(streamingRemainder) : streamingRemainder;
365→            return displayText?.trim() ? (
366→              <div className="message-bubble__segment message-bubble__segment--answer">
367→                <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
368→                <div className="message-bubble__segment-content">
369→                  <ReactMarkdown remarkPlugins={[remarkGfm]}>{displayText}</ReactMarkdown>
370→                </div>
371→              </div>
372→            ) : null;
373→          })()}
374→          {message.segments!.filter((s) => s.type === 'error').map((seg, i) => {
375→            const lastUserMsg = messages.slice().reverse().find((m) => m.role === 'user');
376→            const handleRetry = lastUserMsg ? () => sendMessage(lastUserMsg.content) : undefined;
377→            return <ErrorBlock key={`error-${i}`} errorMessage={seg.errorMessage || 'Unknown error'} onRetry={!isStreaming ? handleRetry : undefined} />;
378→          })}
379→          {message.isStreaming && !message.content && questionSegments.length === 0 && (
380→            <span className="message-bubble__typing">{t('thinking')}</span>
381→          )}
382→        </div>
383→      ) : (
384→        <>
385→          <div className="message-bubble__content">
386→            {message.content ? (
387→              <ReactMarkdown remarkPlugins={[remarkGfm]}>{message.content}</ReactMarkdown>
388→            ) : message.isStreaming ? (
389→              <span className="message-bubble__typing">{t('thinking')}</span>
390→            ) : null}
391→          </div>
392→          {message.toolCalls && message.toolCalls.length > 0 && (
393→            <div className="message-bubble__tools">
394→              {message.toolCalls.map((tc) => (
395→                <InlineQueryResult key={tc.toolCallId} result={tc} />
396→              ))}
397→            </div>
398→          )}
399→        </>
400→      )}
401→    </div>
402→  );
403→}
