462→            if (flushTimerRef.current) {
463→              clearTimeout(flushTimerRef.current);
464→              flushTimerRef.current = null;
465→            }
466→            flushText();
467→            if (currentTextRef.current.trim()) {
468→              segmentsRef.current.push({ type: 'answer', text: currentTextRef.current });
469→              currentTextRef.current = '';
470→            }
471→            setMessages((prev) =>
472→              prev.map((m) =>
473→                m.id === assistantId
474→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
475→                  : m
476→              )
477→            );
478→            setIsStreaming(false);
479→            abortRef.current = null;
480→          },
481→          onError: (error) => {
482→            if (flushTimerRef.current) {
483→              clearTimeout(flushTimerRef.current);
484→              flushTimerRef.current = null;
485→            }
486→            flushText();
487→            if (currentTextRef.current.trim()) {
488→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
489→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
490→              currentTextRef.current = '';
491→            }
492→            segmentsRef.current.push({ type: 'error', errorMessage: error });
493→            setMessages((prev) =>
494→              prev.map((m) =>
495→                m.id === assistantId
496→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
497→                  : m
498→              )
499→            );
500→            setIsStreaming(false);
501→            abortRef.current = null;
502→          },
503→          onUserQuestion: (data) => {
504→            if (flushTimerRef.current) {
505→              clearTimeout(flushTimerRef.current);
506→              flushTimerRef.current = null;
507→            }
508→            flushText();
509→            if (currentTextRef.current.trim()) {
510→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
511→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
512→              currentTextRef.current = '';
513→            }
514→            segmentsRef.current.push({
515→              type: 'user_question',
516→              questionData: data,
517→            });
518→            setMessages((prev) =>
519→              prev.map((m) =>
520→                m.id === assistantId
521→                  ? { ...m, segments: [...segmentsRef.current] }
522→                  : m
523→              )
524→            );
525→          },
526→        },
527→        controller.signal,
528→        userSessionId,
529→      );
530→    },
531→    [isStreaming, messages, flushText, refreshTables, userSessionId]
532→  );
533→
534→  const deleteMessage = useCallback(
535→    (messageIndex: number) => {
536→      if (isStreaming) return;
537→
538→      // Store remaining messages as history for Langfuse context on next send
539→      setMessages((prev) => {
540→        const remaining = prev.slice(0, messageIndex);
541→        pendingHistoryRef.current = remaining
542→          .filter((m) => m.role === 'user' || m.role === 'assistant')
543→          .map((m) => ({ role: m.role, content: m.content }));
544→        return remaining;
545→      });
546→
547→      // Clear session so next message starts fresh
548→      sessionIdRef.current = null;
549→    },
550→    [isStreaming]
551→  );
552→
553→  const respondToQuestion = useCallback(
554→    async (questionId: string, answers: string[], freeText?: string) => {
555→      // Update the segment to show the user's answer
556→      const segIdx = segmentsRef.current.findIndex(
557→        (s) => s.type === 'user_question' && s.questionData?.questionId === questionId
558→      );
559→      if (segIdx !== -1) {
560→        segmentsRef.current[segIdx] = {
561→          ...segmentsRef.current[segIdx],
562→          userAnswer: answers,
563→          userFreeText: freeText,
564→        };
565→        setMessages((prev) =>
566→          prev.map((m) =>
567→            m.id === assistantIdRef.current
568→              ? { ...m, segments: [...segmentsRef.current] }
569→              : m
570→          )
571→        );
572→      }
573→
574→      // POST to backend
575→      try {
576→        await fetch('/api/chat/respond', {
577→          method: 'POST',
578→          headers: {
579→            'Content-Type': 'application/json',
580→            ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
581→          },
582→          body: JSON.stringify({
583→            question_id: questionId,
584→            answers,
585→            free_text: freeText || null,
586→          }),
587→        });
588→      } catch (e) {
589→        console.error('Failed to respond to question:', e);
590→      }
591→    },
592→    [userSessionId]
593→  );
594→
595→  const clearMessages = useCallback(() => {
596→    if (abortRef.current) {
597→      abortRef.current.abort();
598→    }
599→    setMessages([]);
600→    setIsStreaming(false);
601→    sessionIdRef.current = null;
602→    pendingHistoryRef.current = null;
603→  }, []);
604→
605→  return (
606→    <AgentContext.Provider
607→      value={{ messages, isStreaming, sendMessage, editMessage, deleteMessage, clearMessages, respondToQuestion }}
608→    >
609→      {children}
610→    </AgentContext.Provider>
611→  );
612→}
