  1→import { useState, useRef, useEffect } from 'react';
  2→import ReactMarkdown from 'react-markdown';
  3→import remarkGfm from 'remark-gfm';
  4→import { useTranslation } from '../hooks/useTranslation';
  5→import type { ChatMessage, ContentSegment } from '../types';
  6→import { useAgent } from '../hooks/useAgent';
  7→import { InlineQueryResult } from './InlineQueryResult';
  8→import { ChartWidget } from './ChartWidget';
  9→import { UserQuestion } from './UserQuestion';
 10→import './MessageBubble.css';
 11→
 12→/**
 13→ * Strip chart_spec JSON code blocks from answer text.
 14→ * The orchestrator may include the raw chart spec JSON even though the chart
 15→ * is rendered separately. Remove ```json ... ``` blocks containing chart_spec
 16→ * or Plotly trace data so they don't appear as raw text.
 17→ */
 18→function stripChartSpecBlocks(text: string): string {
 19→  return text.replace(/```(?:json)?\s*\n?\s*\{[\s\S]*?"(?:chart_spec|data)"[\s\S]*?\}\s*\n?\s*```/g, '').trim();
 20→}
 21→
 22→/** Strip markdown formatting for plain-text preview display. */
 23→function stripMarkdown(text: string): string {
 24→  return text
 25→    .replace(/\*\*(.+?)\*\*/g, '$1')   // **bold**
 26→    .replace(/__(.+?)__/g, '$1')        // __bold__
 27→    .replace(/\*(.+?)\*/g, '$1')        // *italic*
 28→    .replace(/_(.+?)_/g, '$1')          // _italic_
 29→    .replace(/`(.+?)`/g, '$1')          // `code`
 30→    .replace(/^#+\s+/gm, '');           // # headings
 31→}
 32→
 33→function getLastThinkingLine(segments: ContentSegment[], streamingRemainder: string | undefined, t: (key: string) => string): string {
 34→  // Use streaming remainder if available
 35→  if (streamingRemainder?.trim()) {
 36→    const lines = streamingRemainder.trim().split('\n').filter((l) => l.trim());
 37→    const last = stripMarkdown(lines[lines.length - 1] || '');
 38→    return last.length > 100 ? last.slice(0, 100) + '...' : last;
 39→  }
 40→  // Otherwise use last thinking segment's last line
 41→  for (let i = segments.length - 1; i >= 0; i--) {
 42→    if (segments[i].type === 'thinking' && segments[i].text?.trim()) {
 43→      const lines = segments[i].text!.trim().split('\n').filter((l) => l.trim());
 44→      const last = stripMarkdown(lines[lines.length - 1] || '');
 45→      return last.length > 100 ? last.slice(0, 100) + '...' : last;
 46→    }
 47→  }
 48→  return t('thinking');
 49→}
 50→
 51→function ThinkingBlock({ segments, streamingRemainder, isThinkingPhase, isAgentStreaming, hasAnswer }: {
 52→  segments: ContentSegment[];
 53→  streamingRemainder?: string;
 54→  isThinkingPhase: boolean;
 55→  isAgentStreaming: boolean;
 56→  hasAnswer: boolean;
 57→}) {
 58→  const { t } = useTranslation();
 59→  // All non-answer, non-chart, non-user_question segments go inside the thinking block
 60→  // When hasAnswer is true, subagent_end text segments are shown here instead of in the answer block
 61→  const thinkingSegments = segments.filter(
 62→    (s) => s.type !== 'answer' && s.type !== 'user_question' && !(s.type === 'tool' && s.toolResult?.chart_spec) && !(s.type === 'subagent_end' && (s.chart_spec || (s.text?.trim() && !hasAnswer)))
 63→  );
 64→  const hasContent = thinkingSegments.some(
 65→    (s) => (s.type === 'thinking' && s.text?.trim()) || (s.type === 'tool' && s.toolResult) || s.type === 'subagent_start' || (s.type === 'subagent_end' && !s.chart_spec && s.text?.trim())
 66→  ) || streamingRemainder?.trim();
 67→
 68→  if (!hasContent) return null;
 69→
 70→  // Show preview only while agent is still working (hidden by CSS when collapsible is open anyway)
 71→  const summary = isAgentStreaming ? getLastThinkingLine(segments, streamingRemainder, t) : '';
 72→
 73→  return (
 74→    <details className="message-bubble__segment message-bubble__segment--thinking message-bubble__collapsible" open={isThinkingPhase || undefined}>
 75→      <summary className="message-bubble__collapsible-summary">
 76→        <span className="message-bubble__segment-label">{t('thinkingLabel')}</span>
 77→        {summary && <span className="message-bubble__collapsible-preview">{summary}</span>}
 78→      </summary>
 79→      <div className="message-bubble__thinking-body">
 80→        {thinkingSegments.map((seg, i) => {
 81→          if (seg.type === 'thinking' && seg.text?.trim()) {
 82→            return (
 83→              <div key={i} className="message-bubble__segment-content">
